  function drawYoung(w,h){const v=V.young,plate=w*.30,screen=w*.86,mid=h/2;const lam=v.lambda*1e-9,s=v.s*1e-3,fringe=lam*v.D/s;const scale=Math.min(14000,0.31*h/(fringe*5));sctx.strokeStyle="#7f93aa";sctx.lineWidth=5;sctx.beginPath();sctx.moveTo(plate,40);sctx.lineTo(plate,mid-24);sctx.moveTo(plate,mid-9);sctx.lineTo(plate,mid+9);sctx.moveTo(plate,mid+24);sctx.lineTo(plate,h-40);sctx.stroke();for(let y=35;y<h-35;y++){const pos=(y-mid)/scale;const phase=Math.PI*s*pos/(lam*v.D);const I=Math.cos(phase)**2;sctx.fillStyle=`rgba(120,200,255,${.04+.95*I})`;sctx.fillRect(screen,y,34,1);}sctx.strokeStyle="#eaf6ff";sctx.lineWidth=2;sctx.strokeRect(screen,35,34,h-70);const cy=v.cursor*h;sctx.strokeStyle="#ffd56a";sctx.beginPath();sctx.moveTo(screen-22,cy);sctx.lineTo(screen+55,cy);sctx.stroke();const yPhys=(cy-mid)/scale,phase=Math.PI*s*yPhys/(lam*v.D),I=Math.cos(phase)**2;const m=fringe?yPhys/fringe:0;text("double slit",plate,25,13,"center");text("screen",screen+17,25,13,"center");setReadouts([[`${(fringe*1000).toFixed(3)} mm`,`theoretical fringe spacing w`],[`${(yPhys*1000).toFixed(2)} mm`,`cursor position from centre`],[fmt(I,2),"relative intensity"],[fmt(m,2),"fringe-order coordinate y/w"]]);}
