  function drawFibre(w,h){const v=V.fibre,left=55,right=w-55,top=h*.24,bottom=h*.63,coreTop=h*.34,coreBot=h*.53;sctx.fillStyle="#173b5d";sctx.fillRect(left,top,right-left,bottom-top);sctx.fillStyle="#08233a";sctx.fillRect(left,coreTop,right-left,coreBot-coreTop);sctx.strokeStyle="#67c7ff";sctx.lineWidth=2;sctx.strokeRect(left,coreTop,right-left,coreBot-coreTop);const modes=Math.round(v.modes);for(let m=0;m<modes;m++){const y0=(coreTop+coreBot)/2,amp=8+(m/(Math.max(1,modes-1)))*(coreBot-coreTop)*.43,cycles=1.2+m*.45;sctx.strokeStyle=`hsla(${195+m*15},90%,70%,.65)`;sctx.lineWidth=1.7;sctx.beginPath();for(let x=left;x<=right;x+=3){const y=y0+amp*Math.sin((x-left)/(right-left)*Math.PI*2*cycles);x===left?sctx.moveTo(x,y):sctx.lineTo(x,y);}sctx.stroke();}const modal=v.modal?(modes-1)*2.4*(v.length/1000):0,material=v.material?v.spectral*1.7*(v.length/1000):0,width=12+modal+material,atten=Math.pow(10,-v.absorption*(v.length/1000)/10);const py=h*.82;sctx.strokeStyle="#67c7ff";sctx.lineWidth=3;sctx.beginPath();for(let x=40;x<w*.42;x++){const z=(x-w*.22)/13,y=py-55*Math.exp(-z*z/2);x===40?sctx.moveTo(x,y):sctx.lineTo(x,y);}sctx.stroke();sctx.strokeStyle="#9a86ff";sctx.beginPath();for(let x=w*.55;x<w-35;x++){const z=(x-w*.76)/width,y=py-55*atten*Math.exp(-z*z/2);x===w*.55?sctx.moveTo(x,y):sctx.lineTo(x,y);}sctx.stroke();text("input pulse",w*.22,h*.95,13,"center");text("output pulse",w*.76,h*.95,13,"center");setReadouts([[`${fmt(width,1)} a.u.`,`output pulse width`],[`${fmt(atten*100,1)}%`,`relative output amplitude`],[`${fmt(modal,1)}`,"modal broadening contribution"],[`${fmt(material,1)}`,"material broadening contribution"]]);}
  function drawResonance(w,h){const v=V.resonance,speed=Math.sqrt(v.T/v.mu),f1=speed/(2*v.L),n=Math.max(1,Math.round(v.drive/f1)),fn=n*f1,det=Math.abs(v.drive-fn),amp=clamp(1/Math.sqrt(det*det+v.damping*v.damping),0,.9)/(.9)*Math.min(105,h*.23),mid=h*.45;sctx.strokeStyle="#7890aa";sctx.lineWidth=3;sctx.beginPath();sctx.moveTo(55,mid);sctx.lineTo(w-55,mid);sctx.stroke();sctx.strokeStyle="#67c7ff";sctx.lineWidth=4;sctx.beginPath();for(let x=55;x<=w-55;x+=2){const xi=(x-55)/(w-110),y=mid-amp*Math.sin(n*Math.PI*xi)*Math.cos(studioT*v.drive*2*Math.PI);x===55?sctx.moveTo(x,y):sctx.lineTo(x,y);}sctx.stroke();const gx=60,gy=h*.78,gw=w-120,gh=h*.15;sctx.strokeStyle="#526b84";sctx.strokeRect(gx,gy-gh,gw,gh);sctx.strokeStyle="#9a86ff";sctx.beginPath();for(let px=0;px<gw;px++){const f=5+(px/gw)*175,nn=Math.max(1,Math.round(f/f1)),res=nn*f1,a=1/Math.sqrt((f-res)**2+v.damping**2),yy=gy-clamp(a,0,1/v.damping)*gh*v.damping;px?sctx.lineTo(gx+px,yy):sctx.moveTo(gx+px,yy);}sctx.stroke();const marker=gx+(v.drive-5)/175*gw;sctx.strokeStyle="#ffd56a";sctx.beginPath();sctx.moveTo(marker,gy-gh);sctx.lineTo(marker,gy);sctx.stroke();setReadouts([[`${fmt(f1,2)} Hz`,`fundamental f₁`],[`${n}`,"nearest harmonic n"],[`${fmt(fn,2)} Hz`,`nearest resonance`],[`${fmt(det,2)} Hz`,`distance from resonance`]]);}
