  // ---------- Practical notebook + uncertainty ----------
  function installNotebook(){const view=$("#view-practical");if(!view||$("#advancedNotebook"))return;view.insertAdjacentHTML("beforeend",`<div id="advancedNotebook" style="margin-top:16px"><div class="section-head"><div><span class="eyebrow">Data analysis</span><h2>Virtual practical notebook</h2></div><p class="muted">Store readings, plot a graph and quantify uncertainty. Use it with the built-in practicals or your real laboratory data.</p></div><div class="notebook-shell"><article class="panel pad"><h3>Add a reading</h3><div class="notebook-inputs"><label class="field"><span>x value</span><input id="noteX" type="number" step="any" value="1"></label><label class="field"><span>y value</span><input id="noteY" type="number" step="any" value="1"></label><label class="field"><span>x label</span><input id="noteXLabel" value="x"></label><label class="field"><span>y label</span><input id="noteYLabel" value="y"></label></div><div class="button-row"><button class="button primary" id="addNotebook">Add reading</button><button class="button" id="importPractical">Import current practical table</button><button class="button" id="clearNotebook">Clear</button></div><div class="notebook-table-wrap"><table class="data-table"><thead><tr><th>#</th><th>x</th><th>y</th></tr></thead><tbody id="notebookRows"></tbody></table></div><h3>Uncertainty calculator</h3><div class="uncertainty-grid"><label class="field"><span>Measured value</span><input id="uncValue" type="number" step="any" value="10"></label><label class="field"><span>Absolute uncertainty ±</span><input id="uncAbs" type="number" step="any" value="0.1"></label></div><label class="field"><span>Repeated readings (comma separated)</span><input id="uncRepeats" value="10.1, 9.9, 10.0, 10.2"></label><div class="uncertainty-result" id="uncResult"></div></article><article class="panel pad"><div class="studio-toolbar"><h3>Graph + line of best fit</h3><span class="mini-badge">least-squares fit</span></div><canvas id="notebookGraph" class="notebook-graph"></canvas><div class="equation" id="fitResult">Add at least two readings to calculate a gradient.</div></article></div></div>`);$("#addNotebook").onclick=()=>{S.notebook.push({x:Number($("#noteX").value),y:Number($("#noteY").value)});save();renderNotebook();};$("#clearNotebook").onclick=()=>{S.notebook=[];save();renderNotebook();};$("#importPractical").onclick=importCurrentPractical;["uncValue","uncAbs","uncRepeats"].forEach(id=>$("#"+id).addEventListener("input",renderUncertainty));renderNotebook();renderUncertainty();}
  function importCurrentPractical(){const rows=$$("#practicalRows tr");let added=0;for(const row of rows){const nums=$$("td",row).map(td=>Number(String(td.textContent).replace(/[^0-9eE+.-]/g,""))).filter(Number.isFinite);if(nums.length>=2){S.notebook.push({x:nums[0],y:nums[1]});added++;}}save();renderNotebook();if(added)addMastery("practicals",5);}
  function renderNotebook(){const body=$("#notebookRows");if(body)body.innerHTML=S.notebook.map((r,i)=>`<tr><td>${i+1}</td><td>${fmt(r.x,5)}</td><td>${fmt(r.y,5)}</td></tr>`).join("");drawNotebookGraph();}
  function drawNotebookGraph(){const c=$("#notebookGraph");if(!c)return;const r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);const x=c.getContext("2d");x.setTransform(d,0,0,d,0,0);x.fillStyle="#07131f";x.fillRect(0,0,r.width,r.height);const pad=48,data=S.notebook.filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(data.length<1)return;let xmin=Math.min(...data.map(p=>p.x)),xmax=Math.max(...data.map(p=>p.x)),ymin=Math.min(...data.map(p=>p.y)),ymax=Math.max(...data.map(p=>p.y));if(xmin===xmax){xmin-=1;xmax+=1}if(ymin===ymax){ymin-=1;ymax+=1}const X=v=>pad+(v-xmin)/(xmax-xmin)*(r.width-2*pad),Y=v=>r.height-pad-(v-ymin)/(ymax-ymin)*(r.height-2*pad);x.strokeStyle="#7890aa";x.lineWidth=2;x.beginPath();x.moveTo(pad,20);x.lineTo(pad,r.height-pad);x.lineTo(r.width-20,r.height-pad);x.stroke();for(const p of data){x.fillStyle="#67c7ff";x.beginPath();x.arc(X(p.x),Y(p.y),5,0,Math.PI*2);x.fill();}if(data.length>=2){const n=data.length,sx=data.reduce((a,p)=>a+p.x,0),sy=data.reduce((a,p)=>a+p.y,0),sxx=data.reduce((a,p)=>a+p.x*p.x,0),sxy=data.reduce((a,p)=>a+p.x*p.y,0),den=n*sxx-sx*sx,m=den?(n*sxy-sx*sy)/den:0,b=(sy-m*sx)/n;x.strokeStyle="#ffd56a";x.lineWidth=2.5;x.beginPath();x.moveTo(X(xmin),Y(m*xmin+b));x.lineTo(X(xmax),Y(m*xmax+b));x.stroke();const meanY=sy/n,ssTot=data.reduce((a,p)=>a+(p.y-meanY)**2,0),ssRes=data.reduce((a,p)=>a+(p.y-(m*p.x+b))**2,0),r2=ssTot?1-ssRes/ssTot:1;$("#fitResult").textContent=`y = ${fmt(m,5)}x ${b>=0?"+":"−"} ${fmt(Math.abs(b),5)} · gradient = ${fmt(m,5)} · R² = ${fmt(r2,4)}`;}}
  function renderUncertainty(){const v=Math.abs(Number($("#uncValue")?.value)),u=Math.abs(Number($("#uncAbs")?.value)),arr=String($("#uncRepeats")?.value||"").split(",").map(Number).filter(Number.isFinite),pct=v?u/v*100:NaN,mean=arr.length?arr.reduce((a,b)=>a+b,0)/arr.length:NaN,half=arr.length>1?(Math.max(...arr)-Math.min(...arr))/2:NaN;const h=$("#uncResult");if(h)h.innerHTML=`<strong>${Number.isFinite(pct)?fmt(pct,2)+"%":"—"}</strong> percentage uncertainty · repeat mean <strong>${fmt(mean,4)}</strong> · half-range <strong>±${fmt(half,4)}</strong><br><span class="muted small">Repeats reveal scatter/random uncertainty; they do not remove a systematic offset.</span>`;}

